import{_ as p,C as i,o as e,c as h,a2 as s,b as r,w as a,a as o,E as d,a3 as l}from"./chunks/framework.BC3NdntU.js";const q=JSON.parse('{"title":"4.1 网络分层模型","description":"","frontmatter":{},"headers":[],"relativePath":"卷四-网络与通信/4.1-网络分层模型.md","filePath":"卷四-网络与通信/4.1-网络分层模型.md","lastUpdated":1788944763000}'),u={name:"卷四-网络与通信/4.1-网络分层模型.md"};function c(b,t,E,g,A,P){const n=i("Mermaid");return e(),h("div",null,[t[2]||(t[2]=s('<h1 id="_4-1-网络分层模型" tabindex="-1">4.1 网络分层模型 <a class="header-anchor" href="#_4-1-网络分层模型" aria-label="Permalink to &quot;4.1 网络分层模型&quot;">​</a></h1><blockquote><p>卷:卷四 · 网络与通信 阅读时间:20min</p></blockquote><hr><h2 id="引言-一次请求-数据要-过五关" tabindex="-1">引言:一次请求,数据要&quot;过五关&quot; <a class="header-anchor" href="#引言-一次请求-数据要-过五关" aria-label="Permalink to &quot;引言:一次请求,数据要&quot;过五关&quot;&quot;">​</a></h2><p>分层模型回答一个核心问题:<strong>数据从 A 出发,经过哪些层、每层干了什么,最后到 B</strong>。深挖要懂&quot;封装/解封装&quot;的 PDU 变化,以及 OSI 七层与 TCP/IP 四层的对应。</p><hr><h2 id="一、两套模型" tabindex="-1">一、两套模型 <a class="header-anchor" href="#一、两套模型" aria-label="Permalink to &quot;一、两套模型&quot;">​</a></h2>',7)),(e(),r(l,null,{default:a(()=>[d(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E5%BA%94%E7%94%A8%E5%B1%82%5D%20--%3E%20B%5B%E4%BC%A0%E8%BE%93%E5%B1%82%20TCP%2FUDP%5D%0A%20%20%20%20B%20--%3E%20C%5B%E7%BD%91%E7%BB%9C%E5%B1%82%20IP%5D%0A%20%20%20%20C%20--%3E%20D%5B%E9%93%BE%E8%B7%AF%E5%B1%82%20MAC%5D%0A%20%20%20%20D%20--%3E%20E%5B%E7%89%A9%E7%90%86%E5%B1%82%20%E4%BF%A1%E5%8F%B7%5D%0A%20%20%20%20E%20--%3E%20F%5B%E5%AF%B9%E7%AB%AF%E5%8F%8D%E5%90%91%E8%A7%A3%E5%B0%81%E8%A3%85%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=s('<table tabindex="0"><thead><tr><th>OSI 七层</th><th>TCP/IP 四层</th><th>职责</th><th>协议</th></tr></thead><tbody><tr><td>应用/表示/会话</td><td>应用层</td><td>面向用户</td><td>HTTP、DNS、FTP</td></tr><tr><td>传输层</td><td>传输层</td><td>端到端、端口</td><td>TCP、UDP</td></tr><tr><td>网络层</td><td>网络层</td><td>寻址、路由</td><td>IP、ICMP</td></tr><tr><td>数据链路/物理</td><td>网络接口层</td><td>相邻传输、物理</td><td>以太网、MAC</td></tr></tbody></table><hr><h2 id="二、封装-解封装-每层的-数据单元-pdu" tabindex="-1">二、封装/解封装:每层的&quot;数据单元(PDU)&quot; <a class="header-anchor" href="#二、封装-解封装-每层的-数据单元-pdu" aria-label="Permalink to &quot;二、封装/解封装:每层的&quot;数据单元(PDU)&quot;&quot;">​</a></h2>',3)),(e(),r(l,null,{default:a(()=>[d(n,{id:"mermaid-100",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5B%E5%BA%94%E7%94%A8%E5%B1%82%3A%E6%8A%A5%E6%96%87%20Message%5D%20--%3E%7C%E5%8A%A0%20TCP%20%E5%A4%B4%7C%20B%5B%E4%BC%A0%E8%BE%93%E5%B1%82%3A%E6%AE%B5%20Segment%5D%0A%20%20%20%20B%20--%3E%7C%E5%8A%A0%20IP%20%E5%A4%B4%7C%20C%5B%E7%BD%91%E7%BB%9C%E5%B1%82%3A%E5%8C%85%20Packet%5D%0A%20%20%20%20C%20--%3E%7C%E5%8A%A0%20MAC%20%E5%A4%B4%E5%B0%BE%7C%20D%5B%E9%93%BE%E8%B7%AF%E5%B1%82%3A%E5%B8%A7%20Frame%5D%0A%20%20%20%20D%20--%3E%7C%E8%BD%AC%E7%94%B5%E4%BF%A1%E5%8F%B7%7C%20E%5B%E7%89%A9%E7%90%86%E5%B1%82%3A%E6%AF%94%E7%89%B9%E6%B5%81%20Bits%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=s(`<blockquote><p><strong>PDU 记忆</strong>:报文(Segment 段)→ 包(Packet)→ 帧(Frame)→ 比特。每层只关心自己的头,不管别层内容——这就是&quot;封装&quot;。</p></blockquote><p><strong>一个具体例子(发&quot;你好&quot;)</strong>:应用层 HTTP 组织报文 → 传输层加端口/校验 → 网络层加 IP → 链路层加 MAC → 物理层转信号 → 对端逐层解封装还原。</p><hr><h2 id="三、各层关键概念" tabindex="-1">三、各层关键概念 <a class="header-anchor" href="#三、各层关键概念" aria-label="Permalink to &quot;三、各层关键概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>关键词</th><th>比方</th></tr></thead><tbody><tr><td>应用层</td><td>说什么</td><td>信的内容</td></tr><tr><td>传输层</td><td>怎么可靠送达(端口)</td><td>快递公司</td></tr><tr><td>网络层</td><td>送到哪(IP)</td><td>收件地址</td></tr><tr><td>链路层</td><td>下一跳给谁(MAC)</td><td>中转交接</td></tr></tbody></table><blockquote><p>IP 是&quot;地址&quot;(定位到主机),MAC 是&quot;门牌&quot;(相邻设备),端口是&quot;收件的具体程序&quot;。</p></blockquote><hr><h2 id="四、为什么分层-底层价值" tabindex="-1">四、为什么分层(底层价值) <a class="header-anchor" href="#四、为什么分层-底层价值" aria-label="Permalink to &quot;四、为什么分层(底层价值)&quot;">​</a></h2><ol><li><strong>解耦</strong>:每层独立演进(HTTP/2 换不动 TCP)</li><li><strong>标准化</strong>:层间接口统一,互通</li><li><strong>可替换</strong>:网线换 WiFi,上层无感</li></ol><hr><hr><p><strong>DNS 解析流程(域名 → IP):</strong></p><p>浏览器先查<strong>本地缓存</strong>(浏览器缓存 → 系统 hosts → 路由器 → ISP),都没有则向 DNS 服务器<strong>递归 + 迭代</strong>查询:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 根域名服务器 → 返回 .com 顶级域名服务器地址</span></span>
<span class="line"><span>2. .com 服务器 → 返回 example.com 权威服务器地址</span></span>
<span class="line"><span>3. 权威服务器 → 返回真实 IP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>本地缓存逐层 → 根 → 顶级 → 权威。DNS 慢会拖慢首屏(可用 <code>preconnect</code>/<code>dns-prefetch</code> 提前解析,见 <a href="/frontend-knowledge-base/卷十-性能优化与工程质量/10.2-加载性能.html">10.2</a>)。</p></blockquote><p><strong>TCP 三次握手(建立连接):</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → SYN → 服务器</span></span>
<span class="line"><span>客户端 ← SYN+ACK ← 服务器</span></span>
<span class="line"><span>客户端 → ACK → 服务器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>为什么是三次不是两次?</strong> 两次无法防止&quot;失效的旧连接请求&quot;造成资源浪费;第三次 ACK 让双方都确认&quot;能收能发&quot;。</p><p><strong>四次挥手(断开):</strong> FIN → ACK → FIN → ACK(TCP 全双工,两个方向要分别关闭)。</p><p>📎 官方:<a href="https://developer.mozilla.org/zh-CN/docs/Glossary/DNS" target="_blank" rel="noreferrer">MDN《DNS》</a> · <a href="https://developer.mozilla.org/zh-CN/docs/Glossary/TCP_handshake" target="_blank" rel="noreferrer">TCP 握手</a></p><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分层:应用(HTTP)→ 传输(TCP/UDP,端口)→ 网络(IP,寻址)→ 链路/物理(MAC/信号)</span></span>
<span class="line"><span>封装/解封装:报文→段→包→帧→比特;每层只认自己的头</span></span>
<span class="line"><span>前端关注应用层;断网/换IP等去下面几层找原因</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="六、面试题" tabindex="-1">六、面试题 <a class="header-anchor" href="#六、面试题" aria-label="Permalink to &quot;六、面试题&quot;">​</a></h2><p><strong>Q1:TCP 和 UDP 的区别?</strong></p><table tabindex="0"><thead><tr><th></th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接</td><td>面向连接(三次握手)</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠(重传/顺序)</td><td>不可靠</td></tr><tr><td>速度</td><td>慢</td><td>快</td></tr><tr><td>场景</td><td>HTTP、文件</td><td>视频通话、直播、DNS</td></tr></tbody></table><p><strong>Q2:什么是&quot;封装&quot;和&quot;解封装&quot;?</strong></p><p>封装:发送端<strong>每层加自己的头</strong>(应用→传输加 TCP 头→网络加 IP 头→链路加 MAC 头尾→物理转信号);解封装:接收端<strong>逐层拆头还原</strong>。各层只处理自己这层的协议。</p><p><strong>Q3:IP 地址和 MAC 地址的区别?</strong></p><p>IP 是<strong>网络层</strong>逻辑地址(定位主机、可变化);MAC 是<strong>链路层</strong>物理地址(硬件唯一、局域网内相邻传输用)。类比:IP 是&quot;收件地址&quot;,MAC 是&quot;门牌号&quot;,端口是&quot;收件人&quot;。</p><p><strong>Q4:为什么说前端主要关注&quot;应用层&quot;,但又要懂下面几层?</strong></p><p>前端直接打交道的是应用层(HTTP)。但&quot;断网仍能开页&quot;(缓存,4.3)、&quot;换 IP 后连接变化&quot;、TLS 握手、DNS 慢等性能/排查问题,都要到传输/网络层找原因。分层让&quot;上层能力、下层兜底&quot;。</p><p><strong>Q5:浏览器断网后为什么有时还能&quot;打开&quot;页面?</strong></p><p>因为命中<strong>浏览器 HTTP 缓存</strong>(应用层就返回了缓存),根本没走到传输/网络层。只有缓存未命中、需真网络请求时才因断网失败——&quot;上层能兜底就不麻烦下层&quot;的直接体现。</p><p><strong>Q6:OSI 七层和 TCP/IP 四层的对应关系?</strong></p><p>OSI:应用/表示/会话 → 对应 TCP/IP 应用层;传输层 → 传输层;网络层 → 网络层;数据链路层/物理层 → 网络接口层。TCP/IP 是实际工程模型,OSI 是教学参考。</p><hr><p>📎 参考:<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work" target="_blank" rel="noreferrer">MDN《网络如何工作》</a>、RFC 1122、RFC 1123</p>`,38))])}const m=p(u,[["render",c]]);export{q as __pageData,m as default};
